// === Tab: mySketch ===
let hu = 0;

function setup() {
	createCanvas(w=1112, h=834);
	colorMode(HSB);
	background(100);
	//noLoop();
}

function draw(){
	background(100);  // try commenting out this line
	hu = random(360);

	push();
	strokeWeight(1);
	stroke(hu, 100, 100, 0.2);
	fill(0,0);

	translate(w/2, h/2);

	//Attractor Parameter
	let a0 = PI*random(-1,1);
	let b0 = PI*random(-1,1);
	let c0 = PI*random(-1,1);
	let d0 = PI*random(-1,1);

	let a1 = PI*random(-1,1);
	let b1 = PI*random(-1,1);
	let c1 = PI*random(-1,1);
	let d1 = PI*random(-1,1);

	let a2 = PI*random(-1,1);
	let b2 = PI*random(-1,1);
	let c2 = PI*random(-1,1);
	let d2 = PI*random(-1,1);

	//Draw Parameter
	let draw_scale = 180;
	let N = 600000;

	let x = random(-1,1);
	let y = random(-1,1);

	for(let i=0;i<N;i++){
		let I = random([0, 1, 2]);
		let dx, dy;
		switch(I){
			case 0:
			  //Peter De Jong Attractor
			  dx = sin(a0*y) + cos(b0*x);
			  dy = sin(c0*x) + cos(d0*y);
				point(draw_scale * dx, draw_scale * dy);
			  break;
			case 1:
			  //Peter De Jong Attractor
			  dx = sin(a1*y) + cos(b1*x);
			  dy = sin(c1*x) + cos(d1*y);
			  break;
			case 2:
			  //Peter De Jong Attractor
			  dx = sin(a2*y) + cos(b2*x);
			  dy = sin(c2*x) + cos(d2*y);
			  break;
			default: break;
		}

		x = dx;
		y = dy;

	}
	pop();
	frameRate(1);
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}

